/* CHART DEFAULTS */
const GC='rgba(50,80,200,0.07)',TC='#6677aa',FM='IBM Plex Mono';
Chart.defaults.color=TC;Chart.defaults.font.family=FM;Chart.defaults.font.size=10;
function bo(ext){return Object.assign({responsive:true,maintainAspectRatio:false,
  plugins:{legend:{display:false}},
  scales:{x:{grid:{color:GC},ticks:{color:TC,font:{family:FM,size:10}}},
          y:{grid:{color:GC},ticks:{color:TC,font:{family:FM,size:10}}}}},ext||{});}

/* CARD COLORS — Blank = WHITE */
const CC={K:'#1db87a',Q:'#2272f5',J:'#f53b3b',B:'#ffffff',' ':'#dde6f5'};
const CT={K:'#ffffff',Q:'#ffffff',J:'#ffffff',B:'#334488',' ':'transparent'};

/* DRAW GRID */
function dg(svg,grid,cs,gold){
  svg.innerHTML='';const ns='http://www.w3.org/2000/svg';
  for(let r=0;r<8;r++)for(let c=0;c<8;c++){
    const v=(grid&&grid[r]&&grid[r][c])||' ';
    const rect=document.createElementNS(ns,'rect');
    rect.setAttribute('x',c*cs+.5);rect.setAttribute('y',r*cs+.5);
    rect.setAttribute('width',cs-1);rect.setAttribute('height',cs-1);
    rect.setAttribute('fill',CC[v]||CC[' ']);rect.setAttribute('rx','1');
    if(v==='B'){rect.setAttribute('stroke','#ccc');rect.setAttribute('stroke-width','0.5');}
    svg.appendChild(rect);
    if(v!==' '){
      const t=document.createElementNS(ns,'text');
      t.setAttribute('x',c*cs+cs/2);t.setAttribute('y',r*cs+cs/2+1);
      t.setAttribute('text-anchor','middle');t.setAttribute('dominant-baseline','middle');
      t.setAttribute('fill',CT[v]||'white');t.setAttribute('font-size',cs*.42);
      t.setAttribute('font-weight','700');t.setAttribute('font-family','IBM Plex Mono,monospace');
      t.textContent=v;svg.appendChild(t);
    }
  }
  if(gold){
    const b=document.createElementNS(ns,'rect');
    b.setAttribute('x','1.5');b.setAttribute('y','1.5');
    b.setAttribute('width',8*cs-3);b.setAttribute('height',8*cs-3);
    b.setAttribute('fill','none');b.setAttribute('stroke','#ffb347');
    b.setAttribute('stroke-width','3');b.setAttribute('rx','3');svg.appendChild(b);
  }
}

/* GRID VIEWER */
let GC_='KQJB';
function gvTab(el,c){
  document.querySelectorAll('#gv-tabs .tab').forEach(t=>t.classList.remove('on'));
  el.classList.add('on');GC_=c;
  document.getElementById('gv-cond-l').textContent=c+' — '+PDATA[c].all.length+' exclusive participants';
  document.getElementById('gv-plist-l').textContent='Participant list — '+c+' only';
  gvPop();gvPids();
}
function gvPop(){
  const filt=document.getElementById('gv-filt').value,pd=PDATA[GC_];

  let pids =
    filt==='win'  ? pd.success :
    filt==='fail' ? pd.fail :
    [...pd.success, ...pd.fail].sort((a,b)=>a-b);

  document.getElementById('gv-pid').innerHTML =
    pids.map(p=>`<option value="${p}">P${p}</option>`).join('');

  gvLoadT();
}
function gvLoadT(){
  const pid=document.getElementById('gv-pid').value;
  const trials=(TRIALS[GC_]&&TRIALS[GC_][pid])||[];
  document.getElementById('gv-trial').innerHTML=trials.map((_,i)=>`<option value="${i}">Trial ${i+1}</option>`).join('');
  gvRender();gvStrip(pid,trials);
}
function gvRender(){
  const pid=document.getElementById('gv-pid').value;
  const ti=parseInt(document.getElementById('gv-trial').value)||0;
  const trials=(TRIALS[GC_]&&TRIALS[GC_][pid])||[];
  const tr=trials[ti]||{outcome:'fail',grid:[]};
  dg(document.getElementById('gv-svg'),tr.grid,32,tr.outcome==='win');
  const lbl=document.getElementById('gv-lbl');
  lbl.className='gv-out '+(tr.outcome==='win'?'win':'fail');
  lbl.textContent=tr.outcome==='win'?`Trial ${ti+1} — SUCCESSFUL ✓`:`Trial ${ti+1} — UNSUCCESSFUL ✗`;
  document.querySelectorAll('.tm').forEach((el,i)=>el.classList.toggle('sel',i===ti));
}
function gvStrip(pid,trials){
  const strip=document.getElementById('gv-strip');strip.innerHTML='';
  trials.forEach((tr,i)=>{
    const d=document.createElement('div');d.className='tm'+(i===0?' sel':'');
    d.onclick=()=>{document.getElementById('gv-trial').value=i;gvRender();};
    const lbl=document.createElement('div');lbl.className='tml '+(tr.outcome==='win'?'win':'fail');
    lbl.textContent=tr.outcome==='win'?`T${i+1}✓`:`T${i+1}✗`;
    const ns='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(ns,'svg');svg.setAttribute('width','70');svg.setAttribute('height','70');svg.setAttribute('viewBox','0 0 70 70');
    dg(svg,tr.grid,8.75,tr.outcome==='win');
    d.appendChild(lbl);d.appendChild(svg);strip.appendChild(d);
  });
}
function gvPids(){
  const pd=PDATA[GC_];
  document.getElementById('gv-succ').innerHTML=pd.success.map(p=>`<span class="pid gn" onclick="gvJump(${p})">${p}</span>`).join('');
  document.getElementById('gv-fail').innerHTML=pd.fail.map(p=>`<span class="pid rd" onclick="gvJump(${p})">${p}</span>`).join('');
}
function gvJump(pid){
  document.getElementById('gv-filt').value='all';gvPop();
  document.getElementById('gv-pid').value=pid;gvLoadT();
  document.querySelectorAll('.pid').forEach(c=>c.classList.toggle('hi',parseInt(c.textContent)===pid));
}

/* GRID COMPARISON — matches your Colab code exactly */
let GCC='KQJB',GCI=0;
function gcTab(el,c){
  document.querySelectorAll('#gc-tabs .tab').forEach(t=>t.classList.remove('on'));
  el.classList.add('on');GCC=c;GCI=0;gcRender();
}
function gcNav(dir){GCI+=dir;gcRender();}

function gcRender(){
  const data=COMPARE[GCC];
  const failList=data.unsuccessful;
  const succList=data.successful;
  const nPairs=Math.min(failList.length,succList.length);
  GCI=Math.max(0,Math.min(GCI,nPairs-1));

  document.getElementById('gc-pair-num').textContent=`${GCI+1} / ${nPairs}`;
  document.getElementById('gc-info').textContent=`Pair ${GCI+1} of ${nPairs} — ${GCC} condition`;
  document.getElementById('gc-prev').disabled=GCI===0;
  document.getElementById('gc-next').disabled=GCI===nPairs-1;

  const failPart=failList[GCI];
  const succPart=succList[GCI];

  document.getElementById('gc-fail-hdr').textContent=`✗ Unsuccessful · P${failPart.pid} · ${failPart.trials.length} trial${failPart.trials.length>1?'s':''}`;
  document.getElementById('gc-win-hdr').textContent=`✓ Successful · P${succPart.pid} · solved on trial ${succPart.success_idx+1}`;

  const container=document.getElementById('gc-pair-display');
  container.innerHTML='';

  /* LEFT — unsuccessful participant: all their trials */
  const leftDiv=document.createElement('div');leftDiv.className='cmp-side';
  const leftLbl=document.createElement('div');leftLbl.className='cmp-pid-lbl fail';
  leftLbl.innerHTML=`<span>✗</span> Participant ${failPart.pid} — all ${failPart.trials.length} trial${failPart.trials.length>1?'s':''}`;
  leftDiv.appendChild(leftLbl);
  const leftTrials=document.createElement('div');leftTrials.className='cmp-trials-row';
  failPart.trials.forEach((tr,i)=>{
    const tb=document.createElement('div');tb.className='cmp-trial-block';
    const tlbl=document.createElement('span');tlbl.className='cmp-trial-lbl fail';
    tlbl.textContent=`Trial ${i+1}`;
    const gw=document.createElement('div');gw.className='cmp-grid-wrap';
    const ns='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(ns,'svg');
    const cs=failPart.trials.length<=2?22:failPart.trials.length<=4?18:14;
    svg.setAttribute('width',8*cs);svg.setAttribute('height',8*cs);svg.setAttribute('viewBox',`0 0 ${8*cs} ${8*cs}`);
    dg(svg,tr.grid,cs,false);
    gw.appendChild(svg);tb.appendChild(tlbl);tb.appendChild(gw);leftTrials.appendChild(tb);
  });
  leftDiv.appendChild(leftTrials);container.appendChild(leftDiv);

  /* RIGHT — successful participant: trials up to first success */
  const rightDiv=document.createElement('div');rightDiv.className='cmp-side';
  const rightLbl=document.createElement('div');rightLbl.className='cmp-pid-lbl win';
  rightLbl.innerHTML=`<span>✓</span> Participant ${succPart.pid} — solved on trial ${succPart.success_idx+1}`;
  rightDiv.appendChild(rightLbl);
  const rightTrials=document.createElement('div');rightTrials.className='cmp-trials-row';
  succPart.trials.forEach((tr,i)=>{
    const tb=document.createElement('div');tb.className='cmp-trial-block';
    const isWin=tr.outcome==='win';
    const tlbl=document.createElement('span');
    tlbl.className='cmp-trial-lbl '+(isWin?'last-win':'fail');
    tlbl.textContent=isWin?`Trial ${i+1} ✓`:`Trial ${i+1}`;
    const gw=document.createElement('div');gw.className='cmp-grid-wrap'+(isWin?' gold':'');
    const ns='http://www.w3.org/2000/svg';
    const svg=document.createElementNS(ns,'svg');
    const cs=succPart.trials.length<=2?22:succPart.trials.length<=4?18:14;
    svg.setAttribute('width',8*cs);svg.setAttribute('height',8*cs);svg.setAttribute('viewBox',`0 0 ${8*cs} ${8*cs}`);
    dg(svg,tr.grid,cs,isWin);
    gw.appendChild(svg);tb.appendChild(tlbl);tb.appendChild(gw);rightTrials.appendChild(tb);
  });
  rightDiv.appendChild(rightTrials);container.appendChild(rightDiv);
}

/* HEATMAP */
let HC='KQJB';
function hmTab(el,c){
  document.querySelectorAll('#hm-tabs .tab').forEach(t=>t.classList.remove('on'));
  el.classList.add('on');HC=c;
  document.getElementById('hm-ttl').textContent='Heatmap — '+c+' successful participants';
  document.getElementById('hm-bars-ttl').textContent='Activity — '+c;
  hmRender();
}
function hmRender(){
  const data=HEATMAPS[HC],max=Math.max(...data.flat())||1;
  const tbl=document.getElementById('hm-tbl');tbl.innerHTML='';
  const corner=document.createElement('div');corner.className='hm-c';tbl.appendChild(corner);
  for(let c=0;c<8;c++){const d=document.createElement('div');d.className='hm-lb hm-c';d.textContent=c+1;tbl.appendChild(d);}
  for(let r=0;r<8;r++){
    const rl=document.createElement('div');rl.className='hm-lb hm-c';rl.textContent=String.fromCharCode(65+r);tbl.appendChild(rl);
    for(let c=0;c<8;c++){
      const v=data[r][c],pct=v/max;
      const cell=document.createElement('div');cell.className='hm-c';
      const ri=Math.round(12+pct*230),gi=Math.round(8+pct*35),bi=Math.round(8+pct*35);
      cell.style.background=`rgb(${ri},${gi},${bi})`;
      cell.style.color=pct>0.28?'rgba(255,255,255,.9)':'#444';
      cell.textContent=v>0?v:'';cell.title=`Row ${String.fromCharCode(65+r)}, Col ${c+1}: ${v}`;
      tbl.appendChild(cell);
    }
  }
  const cs=Array(8).fill(0),rs=Array(8).fill(0);
  for(let r=0;r<8;r++)for(let c=0;c<8;c++){cs[c]+=data[r][c];rs[r]+=data[r][c];}
  const mc=Math.max(...cs)||1,mr2=Math.max(...rs)||1;
  function bars(id,vals,mv,labels){
    document.getElementById(id).innerHTML=vals.map((v,i)=>`
      <div class="sbr"><div class="sbl">${labels[i]}</div>
      <div class="sbt"><div class="sbf" style="width:${Math.round(v/mv*100)}%;background:var(--red)"></div></div>
      <div class="sbv">${v}</div></div>`).join('');
  }
  bars('hm-col-bars',cs,mc,['Col 1','Col 2','Col 3','Col 4','Col 5','Col 6','Col 7','Col 8']);
  bars('hm-row-bars',rs,mr2,['Row A','Row B','Row C','Row D','Row E','Row F','Row G','Row H']);
}

/* MOVE SEQUENCES */
let MC_='KQJB';
function msTab(el,c){
  document.querySelectorAll('#ms-tabs .tab').forEach(t=>t.classList.remove('on'));
  el.classList.add('on');MC_=c;msRender();
}
function seqList(id,data,col){
  const el=document.getElementById(id);if(!el)return;
  const mx=data[0]?data[0].n:1;
  el.innerHTML='<div class="slist">'+data.map(d=>`
    <div class="srow"><div class="sbar" style="width:${Math.round(d.n/mx*60+12)}px;background:${col}"></div>
    <div class="stxt">${d.s}</div><div class="sn">${d.n}</div></div>`).join('')+'</div>';
}
function msRender(){
  const d=MOVES[MC_];
  ['sf','ff','sl','fl'].forEach(k=>document.getElementById(`ms-${k}-g`).textContent=MC_);
  seqList('ms-sf',d.sFirst,'#2ecc8a');seqList('ms-sl',d.sLast,'#2ecc8a');
  seqList('ms-ff',d.fFirst,'#ff6b6b');seqList('ms-fl',d.fLast,'#ff6b6b');
}

